import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a new file inside {@code dir} with a name derived from {@code name}.
     * The method protects against directory‑traversal attacks by normalizing the
     * supplied name and ensuring that the resulting file resides within {@code dir}.
     *
     * @param dir  the target directory where the file should be created
     * @param name the desired file name (may contain relative path components)
     * @return a {@link File} instance pointing to a non‑existing file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     * @throws SecurityException        if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        try {
            // Resolve the directory to its canonical form
            File canonicalDir = dir.getCanonicalFile();

            // Ensure the supplied name is a relative path
            Path namePath = Paths.get(name);
            if (namePath.isAbsolute()) {
                throw new SecurityException("Absolute paths are not allowed: " + name);
            }

            // Resolve and normalize the target path
            Path targetPath = canonicalDir.toPath().resolve(namePath).normalize();

            // Verify that the resolved path is still inside the intended directory
            if (!targetPath.startsWith(canonicalDir.toPath())) {
                throw new SecurityException("Attempted directory traversal: " + name);
            }

            File file = targetPath.toFile();

            // Prepare prefix and suffix for unique naming
            String baseName = namePath.getFileName().toString();
            int dotIndex = baseName.lastIndexOf('.');
            String prefix = (dotIndex < 0) ? baseName : baseName.substring(0, dotIndex);
            String suffix = (dotIndex < 0) ? "" : baseName.substring(dotIndex);

            // Find a unique filename if necessary
            int index = 2;
            while (file.exists()) {
                String newName = prefix + "-" + index++ + suffix;
                file = targetPath.getParent().resolve(newName).toFile();
            }

            // Ensure parent directories exist
            file.getParentFile().mkdirs();

            return file;
        } catch (IOException e) {
            // Wrap checked exception into unchecked for callers that expect a File
            throw new RuntimeException("Failed to allocate file", e);
        }
    }

    // other methods

}
