    /**
     * Decompresses data from {@code in} into {@code out}. The method validates
     * the input stream to guard against malformed data and potential denial‑of‑service
     * attacks caused by infinite loops or excessive resource consumption.
     *
     * @param in  the input stream containing compressed data
     * @param out the destination buffer for decompressed data
     * @throws IOException if the input stream ends unexpectedly, contains
     *                     invalid control codes, or the decompressed data would
     *                     overflow the output buffer
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new IOException("Unexpected end of stream while reading run length");
            }

            // A run length of 0 is invalid in the Rgbe format and would cause an infinite loop.
            if (n == 0) {
                throw new IOException("Invalid compressed data: run length of zero");
            }

            if (n > 128) { // Run‑length encoding
                int value = in.read();
                if (value == -1) {
                    throw new IOException("Unexpected end of stream while reading repeated value");
                }

                int repeatCount = n & 0x7F; // lower 7 bits give the repeat count
                if (repeatCount == 0) {
                    throw new IOException("Invalid compressed data: repeat count of zero");
                }

                if (position + repeatCount > total) {
                    throw new IOException("Compressed data exceeds output buffer size");
                }

                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = (byte) value;
                }
            } else { // Literal run
                int literalCount = n; // n is between 1 and 127 inclusive

                if (position + literalCount > total) {
                    throw new IOException("Compressed data exceeds output buffer size");
                }

                for (int i = 0; i < literalCount; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new IOException("Unexpected end of stream while reading literal data");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

    // other methods

    @Override
    public void close() throws IOException {
        in.close();
    }
