import org.apache.shiro.realm.ldap.JndiLdapContextFactory;
import org.apache.shiro.realm.ldap.LdapContextFactory;
import org.apache.shiro.realm.ldap.LdapUtils;
import java.io.IOException;
import java.util.Hashtable;
import javax.naming.AuthenticationException;
import javax.naming.CommunicationException;
import javax.naming.Context;
import javax.naming.NamingException;
import javax.naming.ldap.InitialLdapContext;
import javax.naming.ldap.LdapContext;
import javax.naming.ldap.StartTlsRequest;
import javax.naming.ldap.StartTlsResponse;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider
{
    private final SecurityLog securityLog;

    // other methods

    /**
     * Establishes a secure LDAP context using STARTTLS and authenticates the supplied
     * principal/credentials. The method ensures that authentication succeeds before
     * returning the context, preventing unauthenticated access.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the distinguished name of the user to bind as
     * @param credentials        the password for the user
     * @return an authenticated {@link LdapContext} secured with STARTTLS
     * @throws NamingException if the connection or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {

        if (!(ldapContextFactory instanceof JndiLdapContextFactory)) {
            throw new IllegalArgumentException("Unsupported LdapContextFactory type");
        }
        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }

        JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();

        // Basic environment setup
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiFactory.getUrl());

        // Enforce explicit authentication
        String authMech = jndiFactory.getAuthenticationMechanism();
        if (authMech == null || authMech.trim().isEmpty()) {
            throw new IllegalArgumentException("Authentication mechanism must be specified");
        }
        env.put(Context.SECURITY_AUTHENTICATION, authMech);
        env.put(Context.SECURITY_PRINCIPAL, principal);
        env.put(Context.SECURITY_CREDENTIALS, credentials);

        LdapContext ctx = null;
        StartTlsResponse tls = null;

        try {
            // Create the context with credentials already present
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS before performing any further operations
            StartTlsRequest tlsReq = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(tlsReq);
            tls.negotiate();

            // Perform a harmless lookup to confirm authentication succeeded
            ctx.lookup("");

            return ctx;
        } catch (AuthenticationException ae) {
            // Authentication failed – close context and report
            LdapUtils.closeContext(ctx);
            securityLog.warn(withRealm("LDAP authentication failed for principal '%s' at '%s'",
                    principal, server(jndiFactory)));
            throw ae;
        } catch (IOException | NamingException e) {
            // Connection or negotiation failure – close context and wrap exception
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to establish secure LDAP connection with '%s': %s",
                    server(jndiFactory), e.getMessage()), e);
            throw new CommunicationException(e.getMessage(), e);
        } finally {
            // Ensure TLS resources are released
            if (tls != null) {
                try {
                    tls.close();
                } catch (IOException ignored) {
                    // Ignored – cleanup only
                }
            }
        }
    }

    // other methods
}
