public class XsltRenderer implements Renderer {

    // other methods

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * <p>The method enforces strict security settings on the {@link TransformerFactory}
     * to mitigate the risk of remote code execution via malicious XSLT. It also validates
     * the input stream and guarantees that the stream is closed regardless of success
     * or failure.</p>
     *
     * @param templateStream the XSLT template as an {@link InputStream}
     * @return a securely configured {@link Transformer}
     * @throws IOException if closing the stream fails
     * @throws ProcessingFailedException if the XSLT cannot be parsed or compiled
     */
    private static Transformer createTransformer(InputStream templateStream)
            throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream cannot be null");
        }

        // Create a fresh factory for each call to avoid shared mutable state
        TransformerFactory factory = TransformerFactory.newInstance();

        try {
            // Enable secure processing to prevent XXE and other attacks
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Explicitly deny external DTDs and stylesheets
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");

            // Create the transformer from the provided template
            return factory.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the input stream is always closed
            templateStream.close();
        }
    }

    // other methods
