        final Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            final String entryName = nextEntry.getName();

            // Basic sanity checks
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has null or empty name");
            }

            // Resolve the entry path relative to the target directory and normalize it
            final Path entryPath = targetDirPath.resolve(Paths.get(entryName)).normalize();

