            if (Files.isSymbolicLink(entryPath)) {
                throw new IOException("symbolic link detected in entry: " + entryName);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist
                if (!Files.isDirectory(entryPath)) {
                    try {
