        }

        // Parse components safely
        int fromFirst = parseComponent(fromArr[0], "major", fromVersion);
        int fromMiddle = parseComponent(fromArr[1], "minor", fromVersion);
        int fromEnd = parseComponent(fromArr[2], "patch", fromVersion);

        int toFirst = parseComponent(toArr[0], "major", toVersion);
        int toMiddle = parseComponent(toArr[1], "minor", toVersion);
        int toEnd = parseComponent(toArr[2], "patch", toVersion);

        // Compare major, minor, then patch
        if (fromFirst != toFirst) {
            return Integer.compare(fromFirst, toFirst);
        }
        if (fromMiddle != toMiddle) {
            return Integer.compare(fromMiddle, toMiddle);
        }
