import java.util.Objects;

/**
 * Utility class that determines whether a self‑update request is allowed.
 *
 * <p>The original implementation performed only field‑level equality checks,
 * which allowed an attacker to change another user’s email address if they
 * could guess the target user’s ID.  The patched version now verifies that
 * the authenticated user making the request is the same as the user whose
 * record is being updated.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is permitted to update the
     * specified SCIM user.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Extract the target user ID from the URL path
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 2. Verify that the caller is authenticated and owns the target account
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (!Objects.equals(authenticatedUserId, id)) {
            // The requester is not the owner of the account being updated
            return false;
        }

        // 3. Read and parse the request body
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            return false;
        }

        // 4. Retrieve the current user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere)
            return true;
        }

        // 5. Perform strict field‑by‑field comparison using null‑safe checks
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // 6. All checks passed – the update is allowed
        return true;
    }

    /**
     * Retrieves the authenticated user ID from the request.
     *
     * <p>In a real deployment this would typically come from the security
     * context or a signed JWT.  For the purposes of this example we look
     * for a request attribute named {@code authenticatedUserId} or a
     * header {@code X-Authenticated-User}.  If neither is present,
     * {@code null} is returned.</p>
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if not found
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Object attr = request.getAttribute("authenticatedUserId");
        if (attr instanceof String) {
            return (String) attr;
        }
        String header = request.getHeader("X-Authenticated-User");
        return header != null && !header.isEmpty() ? header : null;
    }
}
